#pragma once
// Placeholder artwork shown in a pane that has no live video source (Android Auto before the phone connects, camera before it is online).
// The art is embedded in the binary (PlaceholderData.cpp, generated by tools/gen-placeholders.py), decoded once with stb_image, and scaled to
// "cover" each pane (centred crop) with optional rounded corners. Scaled copies are cached because panes change size rarely (pinch, layout).
#include <cstdint>
#include <vector>

namespace ui {

enum class Art { AndroidAuto, Camera };

extern const unsigned char kArtAndroidAuto[]; extern const unsigned long kArtAndroidAutoSize;
extern const unsigned char kArtCamera[];      extern const unsigned long kArtCameraSize;

struct Bitmap { int w = 0, h = 0; std::vector<uint8_t> rgba; };

// Decoded source image (RGBA). Empty (w==0) if decoding failed.
const Bitmap& placeholderSource(Art a);

// Art scaled to cover exactly w*h (centred crop, area-average when shrinking, bilinear when enlarging); alpha is 0 outside a rounded rect of
// `radius` px (0 = square corners). Cached; the reference stays valid until the next call that evicts it - copy it out right away.
const std::vector<uint8_t>& placeholderCover(Art a, int w, int h, int radius);

// Same scaling, no cache, no corners: used by tests.
std::vector<uint8_t> scaleCover(const Bitmap& src, int w, int h);

}  // namespace ui
